def process_purchase_orders(center, error_logs, date=None):
	list_of_purchase_orders_for_center = get_list_of_purchase_orders_for_center(center.name, date)
	if list_of_purchase_orders_for_center and len(list_of_purchase_orders_for_center.get("orders")):
		for order in list_of_purchase_orders_for_center.get("orders"):
			process_purchase_order(order, center, error_logs)


def get_list_of_purchase_orders_for_center(center, date=None):
	if date:
		start_date = end_date = date
	else:
		end_date = frappe.utils.nowdate()
		start_date = add_to_date(end_date, days=-1)
	route = "inventory/purchase_orders?center_id="
	url_end = "&show_delivery_details=true&date_criteria=1&status=-1"
	full_url = api_url + route + center + "&start_date=" + start_date + "&end_date=" + end_date + url_end
	all_orders = make_api_call(full_url)
	return all_orders


def process_purchase_order(order, center, error_logs):
	required_data = get_required_data_to_create_purchase_record(order, center, error_logs)
	if required_data:
		for items in required_data:
			supplier_err_msg = check_for_supplier(items["supplier"])
			if supplier_err_msg:
				msg = _("For Order no {}.").format(items["order_number"]) + " " + supplier_err_msg
				error_logs.append(msg)

			item_err_msg_list = check_for_item(items["item_data"], item_group="Products")
			if len(item_err_msg_list):
				item_err_msg = "\n".join(err for err in item_err_msg_list)
				msg = _("For Order no {}.").format(items["order_number"]) + "\n" + item_err_msg
				error_logs.append(msg)

			if not supplier_err_msg and not len(item_err_msg_list):
				create_purchase_record(items)


def check_for_supplier(supplier_code):
	err_msg = ""
	if not supplier_code:
		err_msg = _("Vendor Code is empty")
		return err_msg
	elif not frappe.db.exists("Supplier", {"zenoti_supplier_code": supplier_code}):
		sync_supplier()


def sync_supplier():
	url = api_url + "vendors"
	suppliers = make_api_call(url)
	if suppliers:
		total_page = suppliers["page_info"]["total"] // 100
		for page in range(1, total_page + 2):
			url_ = url + "?size=100&page=" + str(page)
			all_suppliers = make_api_call(url_)
			if all_suppliers:
				for supplier in all_suppliers["vendors"]:
					if not frappe.db.exists("Supplier", {"zenoti_supplier_code": supplier["code"]}):
						try:
							create_supplier(supplier)
						except Exception:
							frappe.log_error()


def create_supplier(supplier_details):
	supplier_details["phone"] = supplier_details["work_phone"]["number"]
	supplier = frappe.new_doc("Supplier")
	supplier.zenoti_supplier_code = supplier_details["code"]
	supplier.supplier_name = supplier_details["name"]
	supplier.supplier_group = (
		frappe.db.get_single_value("Zenoti Settings", "default_supplier_group")
		if frappe.db.get_single_value("Zenoti Settings", "default_supplier_group")
		else "All Supplier Groups"
	)
	supplier.supplier_details = supplier_details["description"]
	supplier.insert()
	make_address(supplier_details, supplier.name, "Supplier")


def get_required_data_to_create_purchase_record(order, center, error_logs):
	data = []
	if not frappe.db.exists(
		"Purchase Invoice", {"zenoti_order_no": order["order_number"]}
	) and not frappe.db.exists("Purchase Order", {"zenoti_order_no": order["order_number"]}):
		cost_center = center.get("erpnext_cost_center")
		if not cost_center:
			err_msg = _("Center {0} is not linked to any ERPNext Cost Center.").format(
				frappe.bold(center.get("center_name"))
			)
			msg = _("For Order no {}.").format(order["order_number"]) + " " + err_msg
			error_logs.append(msg)

		item_data, item_err_msg_list = process_purchase_partials(order.get("partials"), cost_center)
		if len(item_err_msg_list):
			item_err_msg = "\n".join(err for err in item_err_msg_list)
			msg = _("For Order no {}.").format(order["order_number"]) + "\n" + item_err_msg
			error_logs.append(msg)

		if not len(item_err_msg_list):
			date_time = order["ordered_date"].split("T")

			data_dict = {
				"supplier": order["vendor"]["code"],
				"date": date_time[0],
				"time": date_time[1],
				"order_number": order["order_number"],
				"status": order["status"],
				"item_data": item_data,
				"is_return": item_data[0]["is_return"],
				"cost_center": cost_center,
			}
			data.append(data_dict)

	return data


def process_purchase_partials(partials, center):
	item_list = []
	err_msg_list = []
	for item in partials[0]["line_items"]:
		err_msg = check_for_item_tax_template(item["ordered_tax_group_name"])
		if err_msg:
			err_msg_list.append(err_msg)
			continue

		if len(err_msg_list) == 0:
			item_dict = {
				"item_code": item["product_code"],
				"item_name": item["product_name"],
				"supplier_part_no": item["vendor_product_part_number"],
				"rate": item["ordered_unit_price"],
				"item_tax_template": item["ordered_tax_group_name"],
				"cost_center": center,
			}
			item_list.append(item_dict)

	if len(err_msg_list) == 0:
		for item in item_list:
			is_return = False
			qty = 0
			for partial in partials:
				for line_item in partial["line_items"]:
					if item["item_code"] == line_item["product_code"]:
						qty += line_item["ordered_retail_quantity"]
						qty += line_item["ordered_consumable_quantity"]
			if qty < 0:
				is_return = True
				del item["supplier_part_no"]

			item["qty"] = qty
			item["is_return"] = is_return
	return item_list, err_msg_list


def create_purchase_record(order):
	if order["is_return"]:
		doc = frappe.new_doc("Purchase Invoice")
		doc.is_return = 1
		doc.posting_date = order["date"]
		doc.posting_time = order["time"]
		doc.set_posting_time = 1
		doc.cost_center = order["cost_center"]
		doc.update_stock = 1
	else:
		doc = frappe.new_doc("Purchase Order")
		doc.transaction_date = order["date"]
		doc.schedule_date = order["date"]
	doc.zenoti_order_no = order["order_number"]
	supplier = frappe.db.exists("Supplier", {"zenoti_supplier_code": order["supplier"]})
	doc.supplier = supplier
	doc.buying_price_list = frappe.db.get_single_value("Zenoti Settings", "default_buying_price_list")
	doc.set_warehouse = frappe.db.get_single_value("Zenoti Settings", "default_purchase_warehouse")
	doc.set("items", [])
	add_items(doc, order["item_data"])
	add_taxes(doc)
	if order["is_return"]:
		doc.insert()
	else:
		doc.submit()
		status, per_received = get_order_status(order)
		doc.db_set("status", status)
		doc.db_set("per_received", per_received)
		doc.reload()


def add_items(doc, item_data):
	for item in item_data:
		invoice_item = {}
		for key, value in item.items():
			invoice_item[key] = value
			if key == "item_code":
				item_code = frappe.db.get_value(
					"Item",
					{"zenoti_item_code": item["item_code"], "item_name": item["item_name"]},
					"item_code",
				)
				invoice_item["item_code"] = item_code

		if invoice_item.get("item_tax_template"):
			invoice_item["item_tax_template"] = frappe.db.get_value(
				"Item Tax Template", filters={"title": invoice_item["item_tax_template"]}
			)
			invoice_item["item_tax_rate"] = get_item_tax_rate(invoice_item["item_tax_template"])
		doc.append("items", invoice_item)


def get_order_status(order):
	status = "To Receive and Bill"
	per_received = 0
	if order["status"] == "DELIVERED":
		status = "To Bill"
		per_received = 100

	return status, per_received

frappe.ui.form.on(cur_frm.doctype, {
	refresh(frm) {
		if (frm.doc.amended_from) {
			// see if any taxes present
			if (frm.doc.taxes.find((t) => t.dont_recompute_tax)) {
				frappe.msgprint(
					__(
						"Amending document created via E-Commerce integrations will not re-compute taxes. Please check taxes before submitting.",
					),
					__("Warning About Taxes"),
				);
			}
		}
	},
});

import base64
from typing import Any

import frappe
import requests
from frappe import _
from frappe.utils import cint, cstr, get_datetime
from pytz import timezone

from ecommerce_integrations.unicommerce.constants import SETTINGS_DOCTYPE
from ecommerce_integrations.unicommerce.utils import create_unicommerce_log

JsonDict = dict[str, Any]


class UnicommerceAPIClient:
	"""Wrapper around Unicommerce REST API

	API docs: https://documentation.unicommerce.com/
	"""

	def __init__(
		self,
		url: str | None = None,
		access_token: str | None = None,
	):
		self.settings = frappe.get_doc(SETTINGS_DOCTYPE)
		self.base_url = url or f"https://{self.settings.unicommerce_site}"
		self.access_token = [REDACTED]
		self.__initialize_auth()

	def __initialize_auth(self):
		"""Initialize and setup authentication details"""
		if not self.access_token:
			[REDACTED]
			self.access_token = [REDACTED]"access_token")

		self._auth_headers = {"Authorization": f"Bearer {self.access_token}"}

	def _refresh_auth(self):
		"""Fetch a fresh access token after a 401 and rebuild the auth header."""
		self.settings.update_tokens(grant_type="refresh_token")
		self.access_token = [REDACTED]
		self._auth_headers = {"Authorization": f"Bearer {self.access_token}"}

		# Persisting the token (to share it with other clients) is best-effort: a save
		# failure must not block the retry, which already has the new token in-memory.
		try:
			# Background jobs lack write permission on Unicommerce Settings; bypass is
			# intentional so token sharing works without a logged-in session user.
			self.settings.flags.ignore_permissions = True
			self.settings.flags.ignore_custom_fields = True
			self.settings.save()
		except Exception:
			# Best-effort only — log so repeated failures are visible without blocking the retry.
			frappe.log_error("Unicommerce: failed to persist refreshed access token")

	def request(
		self,
		endpoint: str,
		method: str = "POST",
		headers: JsonDict | None = None,
		body: JsonDict | None = None,
		params: JsonDict | None = None,
		files: JsonDict | None = None,
		log_error=True,
	) -> tuple[JsonDict, bool]:
		if headers is None:
			headers = {}

		headers.update(self._auth_headers)

		url = self.base_url + endpoint

		try:
			response = requests.request(
				url=url, method=method, headers=headers, json=body, params=params, files=files
			)
			# Token expired mid-run -> refresh once and retry the call.
			# File uploads are NOT retried: `requests` has already streamed the file
			# object into the first request's body, so the handle is at EOF and
			# replaying it would silently send an empty body. Such calls fall through
			# and fail loudly instead, so the upload can be re-run intact.
			if response.status_code == 401 and not files:
				self._refresh_auth()
				headers.update(self._auth_headers)
				response = requests.request(
					url=url, method=method, headers=headers, json=body, params=params, files=files
				)
			# unicommerce gives useful info in response text, show it in error logs
			response.reason = cstr(response.reason) + cstr(response.text)
			response.raise_for_status()
		except Exception:
			if log_error:
				create_unicommerce_log(status="Error", make_new=True)
			return None, False

		if method == "GET" and "application/json" not in response.headers.get("content-type"):
			return response.content, True

		data = frappe._dict(response.json())
		status = data.successful if data.successful is not None else True

		if not status:
			req = response.request
			url = f"URL: {req.url}"
			body = f"body:  {req.body.decode('utf-8')}"
			request_data = "\n\n".join([url, body])
			message = ", ".join(cstr(error["message"]) for error in data.errors)
			create_unicommerce_log(
				status="Error", response_data=data, request_data=request_data, message=message, make_new=True
			)

		return data, status

	def get_unicommerce_item(self, sku: str, log_error=True) -> JsonDict | None:
		"""Get Unicommerce item data for specified SKU code.

		ref: https://documentation.unicommerce.com/docs/itemtype-get.html
		"""
		item, status = self.request(
			endpoint="/services/rest/v1/catalog/itemType/get", body={"skuCode": sku}, log_error=log_error
		)
		if status:
			return item

	def create_update_item(self, item_dict: JsonDict, update=False) -> tuple[JsonDict, bool]:
		"""Create/update item on unicommerce.

		ref: https://documentation.unicommerce.com/docs/createoredit-itemtype.html
		"""

		endpoint = "/services/rest/v1/catalog/itemType/createOrEdit"
		if update:
			# Edit has separate endpoint even though docs suggest otherwise
			endpoint = "/services/rest/v1/catalog/itemType/edit"
		return self.request(endpoint=endpoint, body={"itemType": item_dict})

	def get_sales_order(self, order_code: str) -> JsonDict | None:
		"""Get details for a sales order.

		ref: https://documentation.unicommerce.com/docs/saleorder-get.html
		"""

		order, status = self.request(
			endpoint="/services/rest/v1/oms/saleorder/get", body={"code": order_code}
		)
		if status and "saleOrderDTO" in order:
			return order["saleOrderDTO"]

	def search_sales_order(
		self,
		from_date: str | None = None,
		to_date: str | None = None,
		status: str | None = None,
		channel: str | None = None,
		facility_codes: list[str] | None = None,
		updated_since: int | None = None,
	) -> list[JsonDict] | None:
		"""Search sales order using specified parameters and return search results.

		ref: https://documentation.unicommerce.com/docs/saleorder-search.html
		"""
		body = {
			"status": status,
			"channel": channel,
			"facility_codes": facility_codes,
			"fromDate": _utc_timeformat(from_date) if from_date else None,
			"toDate": _utc_timeformat(to_date) if to_date else None,
			"updatedSinceInMinutes": updated_since,
		}

		# remove None values.
		body = {k: v for k, v in body.items() if v is not None}

		search_results, status = self.request(endpoint="/services/rest/v1/oms/saleOrder/search", body=body)

		if status and "elements" in search_results:
			return search_results["elements"]
		else:
			frappe.log_error("Failed to search sales orders:", search_results)
			return []

	def get_inventory_snapshot(
		self, sku_codes: list[str], facility_code: str, updated_since: int = 1430
	) -> JsonDict | None:
		"""Get current inventory snapshot.

		ref: https://documentation.unicommerce.com/docs/inventory-snapshot.html
		"""

		extra_headers = {"Facility": facility_code}

		body = {"itemTypeSKUs": sku_codes, "updatedSinceInMinutes": updated_since}

		response, status = self.request(
			endpoint="/services/rest/v1/inventory/inventorySnapshot/get",
			headers=extra_headers,
			body=body,
		)

		if status:
			return response

	def bulk_inventory_update(self, facility_code: str, inventory_map: dict[str, int]):
		"""Bulk update inventory on unicommerce using SKU and qty.

		The qty should be "total" quantity.
		ref: https://documentation.unicommerce.com/docs/adjust-inventory-bulk.html
		"""

		extra_headers = {"Facility": facility_code}

		inventory_adjustments = []
		for sku, qty in inventory_map.items():
			inventory_adjustments.append(
				{
					"itemSKU": sku,
					"quantity": qty,
					"shelfCode": "DEFAULT",  # XXX
					"inventoryType": "GOOD_INVENTORY",
					"adjustmentType": "REPLACE",
					"facilityCode": facility_code,
				}
			)

		response, status = self.request(
			endpoint="/services/rest/v1/inventory/adjust/bulk",
			headers=extra_headers,
			body={"inventoryAdjustments": inventory_adjustments},
		)

		if not status:
			return response, status
		else:
			# parse result by item
			try:
				item_wise_response = response["inventoryAdjustmentResponses"]
				item_wise_status = {
					item["facilityInventoryAdjustment"]["itemSKU"]: item["successful"]
					for item in item_wise_response
				}
				if False in item_wise_status.values():
					create_unicommerce_log(
						status="Failure",
						response_data=response,
						message="Inventory sync failed for some items",
						make_new=True,
					)
				return item_wise_status, status
			except Exception:
				return response, False

	def create_sales_invoice(
